function displayPreview(p,forceFit=false){const image=$('#diagram-image');if(blobURL)URL.revokeObjectURL(blobURL);blobURL=URL.createObjectURL(new Blob([p.svg],{type:'image/svg+xml;charset=utf-8'}));image.src=blobURL;image.width=p.width;image.height=p.height;image.alt=active()?.title||'Mermaid diagram';image.hidden=false;$('#empty-preview').hidden=true;$('#canvas').style.setProperty('--canvas',p.background||'#f7f7f2');$('#canvas').style.setProperty('--canvas-text',p.visual.theme==='night'?'#b2c5d1':'#455655');$('#render-metrics').textContent=`${Math.round(p.width)} × ${Math.round(p.height)} · ${p.elapsed} ms`;lastPreviewDoc=p.docId;markPreviewStale();if(forceFit||state.settings.autoFit)requestAnimationFrame(fitView);}
function isCurrentPreview(){const d=active(),p=d&&previews.get(d.id);return!!(d&&p&&p.source===d.source&&p.visualKey===visualKey(d.visual));}
function markPreviewStale(){const d=active(),p=d&&previews.get(d.id),valid=isCurrentPreview();$('#stale-banner').hidden=!p||valid;if(p&&!valid)$('#stale-banner').textContent=currentError?'Last valid preview · current source needs attention':'Preview is behind the source · render to update';if(valid){clearError();currentError=null;$('#render-badge').textContent='Valid';$('#render-badge').classList.remove('error');$('#render-state').innerHTML='<i class="led"></i>Source rendered successfully';}else if(p&&!currentError){$('#render-badge').textContent=state.settings.live?'Updating':'Paused';$('#render-state').innerHTML='<i class="led" style="background:var(--warning)"></i>Preview not current';}}
function transformView(){view.scale=Math.max(.04,Math.min(8,view.scale));$('#diagram-transform').style.transform=`translate(${view.x}px,${view.y}px) scale(${view.scale})`;$('#zoom-value').textContent=Math.round(view.scale*100)+'%';}
function fitView(){const d=active(),p=d&&previews.get(d.id),canvas=$('#canvas');if(!p||canvas.clientWidth<5||canvas.clientHeight<5)return;const w=canvas.clientWidth,h=canvas.clientHeight;view.scale=Math.max(.04,Math.min(1.5,(w-70)/p.width,(h-130)/p.height));view.x=(w-p.width*view.scale)/2;view.y=62+(h-125-p.height*view.scale)/2;transformView();}
function zoom(factor,cx,cy){const canvas=$('#canvas');cx??=canvas.clientWidth/2;cy??=canvas.clientHeight/2;const old=view.scale,next=Math.max(.04,Math.min(8,old*factor));view.x=cx-(cx-view.x)*(next/old);view.y=cy-(cy-view.y)*(next/old);view.scale=next;transformView();}
function setupCanvas(){const canvas=$('#canvas');const points=new Map();let previousDistance=0;canvas.addEventListener('wheel',e=>{if(e.target.closest('button,select'))return;e.preventDefault();const r=canvas.getBoundingClientRect();zoom(Math.exp(-e.deltaY*.0018),e.clientX-r.left,e.clientY-r.top)},{passive:false});canvas.addEventListener('pointerdown',e=>{if(e.target.closest('button,select'))return;canvas.setPointerCapture(e.pointerId);points.set(e.pointerId,{x:e.clientX,y:e.clientY});canvas.focus({preventScroll:true});if(points.size===2){const p=[...points.values()];previousDistance=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y);}});canvas.addEventListener('pointermove',e=>{if(!points.has(e.pointerId))return;const old=points.get(e.pointerId);points.set(e.pointerId,{x:e.clientX,y:e.clientY});if(points.size===1){view.x+=e.clientX-old.x;view.y+=e.clientY-old.y;transformView();}else if(points.size===2){const p=[...points.values()],distance=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y),r=canvas.getBoundingClientRect();if(previousDistance)zoom(distance/previousDistance,(p[0].x+p[1].x)/2-r.left,(p[0].y+p[1].y)/2-r.top);previousDistance=distance;}});for(const event of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(event,e=>{points.delete(e.pointerId);previousDistance=0;});canvas.addEventListener('keydown',e=>{if(e.target!==canvas)return;const step=e.shiftKey?80:25;if(e.key.startsWith('Arrow')){e.preventDefault();view.x+=(e.key==='ArrowLeft'?step:e.key==='ArrowRight'?-step:0);view.y+=(e.key==='ArrowUp'?step:e.key==='ArrowDown'?-step:0);transformView();}else if(e.key==='+'||e.key==='='){e.preventDefault();zoom(1.2)}else if(e.key==='-'){e.preventDefault();zoom(1/1.2)}else if(e.key.toLowerCase()==='f'){e.preventDefault();fitView()}else if(e.key==='0'){e.preventDefault();zoom(1/view.scale)}});
const splitter=$('#splitter');splitter.addEventListener('pointerdown',e=>{e.preventDefault();splitter.setPointerCapture(e.pointerId);const area=$('#work-area');const move=ev=>{const rect=area.getBoundingClientRect();state.settings.split=Math.round(Math.max(25,Math.min(70,(ev.clientX-rect.left)/rect.width*100)));$('#source-region').style.width=state.settings.split+'%';splitter.setAttribute('aria-valuenow',state.settings.split);editor.refresh();};const end=()=>{splitter.removeEventListener('pointermove',move);splitter.removeEventListener('pointerup',end);splitter.removeEventListener('pointercancel',end);markDirty();if(state.settings.autoFit)fitView();};splitter.addEventListener('pointermove',move);splitter.addEventListener('pointerup',end);splitter.addEventListener('pointercancel',end);});splitter.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();state.settings.split=Math.max(25,Math.min(70,state.settings.split+(e.key==='ArrowLeft'?-2:2)));applyUI();markDirty();});new ResizeObserver(()=>{editor?.refresh();if(state?.settings.autoFit)fitView()}).observe($('#work-area'));}
