function compareSnapshot(id){const d=active(),s=d?.snapshots.find(s=>s.id===id);if(!s)return;const diff=C.diffLines(s.source,d.source),added=diff.filter(x=>x.kind==='add').length,removed=diff.filter(x=>x.kind==='remove').length;showModal('Compare with '+s.title,`<p>${added} added line${added===1?'':'s'} · ${removed} removed line${removed===1?'':'s'} · Snapshot ${esc(prettyTime(s.created))}</p>${visualKey(s.visual)!==visualKey(d.visual)?'<div class="callout">Appearance settings also differ from this snapshot.</div>':''}<div class="diff-view">${diff.map(x=>`<div class="diff-line ${x.kind}"><b>${x.kind==='add'?'+':x.kind==='remove'?'−':' '}</b><span>${esc(x.text)||' '}</span></div>`).join('')}</div><div class="modal-actions"><button class="button secondary" data-action="close-modal">Keep current version</button><button class="button primary" data-restore="${esc(id)}">Restore snapshot</button></div>`,'medium','HISTORY / BASELINE COMPARISON');}
